/**
 * SizeOf (CollSize) eval — fixture-driven test (phase 2f Coll HOFs Task 2).
 *
 * Tests the `SizeOf` arm of the evaluator. SizeOf returns `Int(items.length)`
 * from a Coll SValue.
 *
 * Cost: Fixed(14), charged BEFORE eval-child (Pattern A).
 * Sigma-rust ref: ergotree-interpreter/src/eval/coll_size.rs:11-22
 *   ctx.add_jit_cost(14)?;   // line 15 — Pattern A
 *   let input_v = self.input.eval(env, ctx)?;  // line 16
 *
 * Fixtures generated by `fixture-gen/src/cmds/ergoscript/eval/coll_size.rs`
 * (sigma-rust oracle; byte-equality check for success entries).
 *
 * Entries:
 *   1. coll_size_int_5      — Coll[Int]([10,20,30,40,50]) → Int(5), cost=59
 *   2. coll_size_empty      — Coll[Int]([]) → Int(0), cost=34
 *   3. coll_size_long_3     — Coll[Long]([1L,2L,3L]) → Int(3), cost=49
 *   4. coll_size_nested_2   — Coll[Coll[Byte]]([…,…]) → Int(2), cost=89
 *   5. coll_size_cost_limit — jitCostLimit=10 → 'cost-limit-exceeded'
 *   6. coll_size_not_coll   — SizeOf(Const(SInt,42)) → 'coll-input-not-coll'
 */

import { describe, it, expect } from 'vitest'
import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseTree } from '../../src/wire/ergo-tree'
import { evaluateWith } from '../../src/eval/evaluate'
import { makeContext } from '../../src/eval/eval-context'
import { hexToBytes, hydrateSValue, captureEvalError, rehydrateEvalOpts } from '../_helpers'

const __dirname = dirname(fileURLToPath(import.meta.url))

interface CollSizeFixtureEntry {
  name: string
  tree_bytes_hex: string
  opts_json: Record<string, unknown>
  expected_value_json: unknown
  expected_cost: number
  expected_error_code: string | null
}

interface CollSizeFixtureFile {
  corpus: string
  entries: CollSizeFixtureEntry[]
}

const FIXTURE_PATH = join(__dirname, '../fixtures/eval/coll-size.json')
const fixture: CollSizeFixtureFile = JSON.parse(readFileSync(FIXTURE_PATH, 'utf-8'))

describe('SizeOf eval (phase 2f Coll HOFs Task 2)', () => {
  for (const entry of fixture.entries) {
    it(entry.name, () => {
      const tree = parseTree(hexToBytes(entry.tree_bytes_hex))
      const opts = rehydrateEvalOpts(entry.opts_json)
      const ctx = makeContext(opts)

      if (entry.expected_error_code !== null) {
        const err = captureEvalError(() => evaluateWith(tree, ctx))
        expect(err.code).toBe(entry.expected_error_code)
      } else {
        const result = evaluateWith(tree, ctx)
        expect(result).toEqual(hydrateSValue(entry.expected_value_json))
        expect(ctx.jitCost).toBe(entry.expected_cost)
      }
    })
  }
})
